// Lexicon Track C7d: the tipping calculator's rates as line statements, and the "last checked" line on its page.
// Soli Deo Gloria.
//
// The read model (assets/data/lexicon/tipping-checked.json) is generated by admin/lexicon/package-statements.mjs; that
// it is current is pinned by lexicon-package-statements.test.mjs ("exactly what the files say"). This file pins what is
// filed from the tipping files, what is left out and why, and what the page may say with it.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { readTipping, rateDisagreementsOf, TIER_PROPERTY } from '../../admin/lexicon/package-statements.mjs';
import * as checked from '../../assets/js/tools/cruise-tipping-calculator/checked.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (rel) => readFileSync(path.join(ROOT, rel), 'utf8');
const MODEL = JSON.parse(read('assets/data/lexicon/tipping-checked.json'));
const REVIEW = JSON.parse(read('assets/data/lexicon/package-review.json'));
const PACK = JSON.parse(read('assets/data/lexicon/cruise.line.pack.json'));
const TIP_DIR = 'assets/data/tipping';
const tipFiles = readdirSync(path.join(ROOT, TIP_DIR)).filter((f) => f.endsWith('.json') && !f.startsWith('_')).sort();
const ms = (iso) => Date.parse(iso);
const DAY = 86400000;

test('the note says when the details were last checked, and says they may be out of date past the window', () => {
  const entry = { checked: '2026-05-08', stale_after: '2026-07-07T00:00:00.000Z', statements: [] };
  const fresh = checked.note(entry, ms('2026-06-01T00:00:00Z'));
  assert.equal(fresh.state, 'fresh');
  assert.equal(fresh.text, 'Tipping details last checked May 8, 2026.');
  assert.equal(checked.note(entry, ms('2026-07-07T00:00:00.000Z')).state, 'fresh', 'the last fresh instant is still fresh');
  const stale = checked.note(entry, ms('2026-07-07T00:00:00.001Z'));
  assert.equal(stale.state, 'stale');
  assert.equal(stale.text, 'Tipping details last checked May 8, 2026, so they may be out of date. Confirm with the cruise line before you sail.');
});

test('nothing is said for a missing entry, an unreadable date, or a bad clock', () => {
  const entry = { checked: '2026-05-08', stale_after: '2026-07-07T00:00:00.000Z' };
  assert.equal(checked.note(null, Date.now()), null);
  assert.equal(checked.note({ ...entry, checked: 'May 8' }, Date.now()), null);
  assert.equal(checked.note({ ...entry, stale_after: 'never' }, Date.now()), null);
  assert.equal(checked.note(entry, NaN), null);
  assert.equal(checked.longDate('2026-13-01'), null);
  assert.equal(checked.accept({ format: 'other', lines: {} }), null);
  assert.equal(checked.accept({ format: 'itw-tipping-checked/1', lines: [] }), null);
});

test('render fills text only, hides when there is no record, and never reads an inherited line', async () => {
  const el = () => ({ textContent: 'old', hidden: false, attrs: {}, setAttribute(n, v) { this.attrs[n] = v; }, removeAttribute(n) { delete this.attrs[n]; } });
  checked.reset();
  await checked.load(async () => ({ ok: true, json: async () => MODEL }));
  const a = el();
  checked.render(a, 'carnival', ms('2026-11-04T00:00:00Z'));
  assert.equal(a.hidden, false);
  assert.match(a.textContent, /^Tipping details last checked May 8, 2026, so they may be out of date\./);
  assert.equal(a.attrs['data-state'], 'stale');
  const b = el();
  checked.render(b, 'no-such-line');
  assert.equal(b.hidden, true);
  assert.equal(b.textContent, '', 'old text is cleared, not left behind a hidden flag');
  const c = el();
  checked.render(c, '__proto__');
  assert.equal(c.hidden, true);

  checked.reset();
  await checked.load(async () => ({ ok: true, json: async () => ({ format: 'itw-tipping-checked/1', lines: Object.create({ carnival: MODEL.lines.carnival }) }) }));
  const d = el();
  checked.render(d, 'carnival');
  assert.equal(d.hidden, true, 'an inherited line is not in the record');

  checked.reset();
  await checked.load(async () => ({ ok: false, json: async () => MODEL }));
  const e = el();
  checked.render(e, 'carnival');
  assert.equal(e.hidden, true, 'no record, no date');
  checked.reset();
});

test("every line's date is its tipping file's own verified date, and every tipping file is covered", () => {
  const ttl = PACK.properties.gratuities_in_fare.ttl_days;
  assert.equal(ttl, 60, 'the re-verify cadence task sets 60 days');
  for (const f of tipFiles) {
    const d = JSON.parse(read(`${TIP_DIR}/${f}`));
    const entry = MODEL.lines[d.lineId];
    assert.ok(entry, `${d.lineId} is in the record`);
    assert.equal(entry.checked, d.verifiedAt, d.lineId);
    assert.equal(ms(entry.stale_after), ms(`${d.verifiedAt}T00:00:00.000Z`) + ttl * DAY, d.lineId);
    assert.ok(entry.statements.length >= 1, d.lineId);
  }
  assert.equal(Object.keys(MODEL.lines).length, tipFiles.length);
});

test('a bundled line files only that its fare includes gratuities; a regional line files no one region for all', () => {
  const { facts, notFiled } = readTipping(ROOT);
  for (const f of tipFiles) {
    const d = JSON.parse(read(`${TIP_DIR}/${f}`));
    const mine = facts.filter((x) => x.line === d.lineId);
    const inFare = mine.filter((x) => x.property === 'gratuities_in_fare');
    assert.equal(inFare.length, 1, d.lineId);
    assert.equal(inFare[0].value, d.bundledInFare, d.lineId);
    if (d.bundledInFare) assert.equal(mine.length, 1, `${d.lineId}: nothing else is charged`);
    if (!d.bundledInFare && (d.region !== 'global' || Array.isArray(d.regions))) {
      assert.equal(mine.length, 1, `${d.lineId}: regional rates are not filed`);
      assert.ok(notFiled.some((n) => n.source.includes(`${TIP_DIR}/${f}#dailyRates`) && /vary by region/.test(n.reason)), d.lineId);
    }
    for (const x of mine) assert.equal(x.checked, `${d.verifiedAt}T00:00:00.000Z`, `${d.lineId} ${x.property}`);
  }
});

test("Holland America's announced change is filed as a second figure from its date, so the two do not conflict", () => {
  const hal = readTipping(ROOT).facts.filter((x) => x.line === 'holland-america');
  const std = hal.filter((x) => x.property === 'daily_gratuity_standard');
  assert.deepEqual(std.map((x) => [x.value, x.validFrom ?? null, x.validUntil ?? null]).sort(), [
    [17, null, '2026-06-01T00:00:00.000Z'], [18, '2026-06-01T00:00:00.000Z', null],
  ]);
  const bar = hal.filter((x) => x.property === 'bar_gratuity_rate').map((x) => x.value).sort();
  assert.deepEqual(bar, [0.18, 0.2]);
  const windowed = new Set(['bar_gratuity_rate', 'daily_gratuity_standard', 'daily_gratuity_suite']);
  assert.ok(!REVIEW.disputes.some((d) => d.entity === 'line:holland-america' && windowed.has(d.property)), 'windows that touch are not a dispute');
});

test('the bar gratuity and the drink calculator package rate are compared, and a difference is named', () => {
  const lines = REVIEW.tipping.rate_disagreements.map((d) => d.line);
  assert.ok(lines.includes('line:princess'), 'Princess: the older line file still says 18%, the tipping file 20%');
  const princess = REVIEW.tipping.rate_disagreements.find((d) => d.line === 'line:princess');
  assert.deepEqual([...new Set(princess.beverage_gratuity_rate.map((x) => x.value))].sort(), [0.18, 0.2]);
  assert.deepEqual(princess.bar_gratuity_rate.map((x) => x.value), [0.2]);
  assert.ok(!lines.includes('line:royal-caribbean'), 'both say 18%');
  const s = (entity, property, value) => ({ ext: { entity, property, value }, epistemic: { evidence: [{ ref: 'r' }] }, timestamps: {} });
  assert.deepEqual(rateDisagreementsOf([s('line:a', 'beverage_gratuity_rate', 0.18), s('line:a', 'bar_gratuity_rate', 0.18)]), []);
  assert.equal(rateDisagreementsOf([s('line:a', 'beverage_gratuity_rate', 0.18), s('line:a', 'bar_gratuity_rate', 0.2)]).length, 1);
  assert.deepEqual(rateDisagreementsOf([s('line:a', 'bar_gratuity_rate', 0.2)]), [], 'one store alone is nothing to compare');
});

test("C7e: the drink calculator's Princess and Holland America rate is the lines' current 20%, dated by its own note", () => {
  const calc = JSON.parse(read('assets/data/calculator-config.json'));
  const checkedModel = JSON.parse(read('assets/data/lexicon/calculator-checked.json'));
  for (const [key, line] of [['princess', 'line:princess'], ['holland', 'line:holland-america']]) {
    const l = calc.lines[key];
    assert.equal(l.rules.gratuity, 0.2, key);
    assert.match(l._sources.gratuityNote, /\b20%/, `${key}: the note states the rate in words`);
    assert.match(l._sources.gratuityNote, /verified 2026-11-04/, `${key}: the note dates the rate`);
    for (const [tier, p] of Object.entries(l.packages)) {
      assert.ok(!/\+18% gratuity/.test(p.priceNote ?? ''), `${key}.${tier}: no package note still adds 18%`);
    }
    for (const [tier, e] of Object.entries(checkedModel.lines[key])) {
      if (e.gratuity_rate === undefined) continue;
      assert.equal(e.gratuity_rate, 0.2, `${key}.${tier}`);
      assert.equal(e.rate_checked, '2026-11-04', `${key}.${tier}: the rate is dated by the note`);
      assert.equal(e.checked, '2026-04-17', `${key}.${tier}: the price keeps its own older check date`);
    }
    // What still disagrees comes only from the older per-line file, which this change does not touch, so its prices
    // are not re-dated by a commit that never checked them.
    const d = REVIEW.tipping.rate_disagreements.find((x) => x.line === line);
    const stale = d.beverage_gratuity_rate.filter((x) => x.value !== 0.2);
    assert.ok(stale.length >= 1, `${line}: the older line file is still named`);
    for (const s of stale) assert.ok(s.refs.every((r) => r.startsWith('itw:assets/data/lines/')), `${line}: ${s.refs}`);
  }
});

test('a tier with no property, a non-dollar rate and an undated file are listed with their reasons, never filed', (t) => {
  const root = mkdtempSync(path.join(tmpdir(), 'itw-c7d-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  mkdirSync(path.join(root, TIP_DIR), { recursive: true });
  writeFileSync(path.join(root, 'assets/data/brands.json'), JSON.stringify({ brands: [{ id: 'a' }, { id: 'b' }, { id: 'c' }] }));
  const base = { region: 'global', currency: 'USD', verifiedAt: '2026-05-08', bundledInFare: false, autoGratuities: { bar: { percent: 18 } } };
  const put = (id, extra) => writeFileSync(path.join(root, TIP_DIR, `${id}.json`), JSON.stringify({ lineId: id, ...base, ...extra }));
  put('a', { dailyRates: { tiers: [{ slug: 'standard', amount: 17 }, { slug: 'grand-loft', amount: 40 }] } });
  put('b', { currency: 'EUR', dailyRates: { tiers: [{ slug: 'standard', amount: 12 }] } });
  put('c', { verifiedAt: undefined, dailyRates: { tiers: [{ slug: 'standard', amount: 17 }] } });
  writeFileSync(path.join(root, TIP_DIR, 'z.json'), JSON.stringify({ lineId: 'z', ...base }));
  const { facts, notFiled, unmatched } = readTipping(root);
  assert.deepEqual(facts.filter((x) => x.line === 'a').map((x) => x.property).sort(), ['bar_gratuity_rate', 'daily_gratuity_standard', 'gratuities_in_fare']);
  assert.ok(notFiled.some((n) => n.source.endsWith('a.json#dailyRates.tiers.grand-loft.amount') && /no property/.test(n.reason)));
  assert.deepEqual(facts.filter((x) => x.line === 'b').map((x) => x.property), ['gratuities_in_fare']);
  assert.ok(notFiled.some((n) => n.source.endsWith('b.json#currency') && /EUR/.test(n.reason)));
  assert.equal(facts.filter((x) => x.line === 'c').length, 0, 'no verified date: nothing is dated, so nothing is filed');
  assert.ok(notFiled.some((n) => n.source.endsWith('c.json#verifiedAt')));
  assert.deepEqual(unmatched.map((u) => u.key), ['z'], 'a line id brands.json does not know');
  for (const slug of Object.keys(TIER_PROPERTY)) assert.ok(PACK.properties[TIER_PROPERTY[slug]], `${slug} has a pack property`);
});

test('the page wires the line in, sets text only, and keeps the noscript rates note', () => {
  const src = read('assets/js/tools/cruise-tipping-calculator/checked.js');
  for (const banned of ['innerHTML', 'outerHTML', 'insertAdjacentHTML', 'eval(', 'new Function', 'document.write']) assert.ok(!src.includes(banned), banned);
  const main = read('assets/js/tools/cruise-tipping-calculator/main.js');
  assert.match(main, /import \{ load as loadChecked, render as renderChecked \} from "\.\/checked\.js";/);
  assert.match(main, /renderChecked\(\$\("#rates-checked"\), v\.line\);/);
  assert.match(main, /loadChecked\(\)\.then/);
  const html = read('tools/cruise-tipping-calculator.html');
  assert.ok(html.includes('<p id="rates-checked" class="tiny" hidden></p>'));
});
